@app.route('/api/price/<symbol>')
def get_price(symbol):
    """Obtiene el precio actual de un símbolo, usando Binance o DolarApi según corresponda."""
    # Mapeo de símbolos a fuentes
    # Aquí deberías tener un mapeo más robusto, pero por ahora usaremos una lógica simple
    if symbol.endswith('USDT'):
        # Es un par de Binance
        try:
            response = requests.get(f'https://api.binance.com/api/v3/ticker/price?symbol={symbol}')
            data = response.json()
            return jsonify({'price': float(data['price']), 'symbol': symbol})
        except Exception as e:
            return jsonify({'error': str(e)}), 400
    elif symbol.startswith('USD-'):
        # Es un dólar de Argentina
        dolar_type = symbol.split('-')[1].lower()
        try:
            response = requests.get(f'https://dolarapi.com/v1/dolares/{dolar_type}')
            data = response.json()
            # Usamos el valor de compra
            return jsonify({'price': float(data['compra']), 'symbol': symbol})
        except Exception as e:
            return jsonify({'error': str(e)}), 400
    else:
        return jsonify({'error': 'Símbolo no soportado'}), 400

