const handlePredict = async () => {
  if (!realPrice) return;
  setLoading(true);
  setError(null);

  try {
    const response = await fetch(`${API_URL}/api/advanced/predict`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        symbol: selectedAsset.symbol,
        timeValue: timeValue,
        timeUnit: timeUnit,
        confidence: 0.95, // por defecto
        model: 'nonlinear' // por defecto
      })
    });

    const data = await response.json();
    if (data.error) throw new Error(data.error);

    // Transformar la respuesta del backend al formato que espera el frontend
    // El backend devuelve: history.dates, history.prices, forecastDates, prediction.median, etc.
    // Necesitamos convertir esto a un array de { label, price, isForecast }

    const historyData = data.history.prices.map((price, index) => ({
      label: data.history.dates[index],
      price: price,
      isForecast: false
    }));

    const forecastData = data.prediction.median.map((price, index) => ({
      label: data.forecastDates[index],
      price: price,
      isForecast: true
    }));

    const chartData = [...historyData, ...forecastData];

    setPrediction({
      predictedPrice: data.prediction.median[data.prediction.median.length - 1],
      changePercent: ((data.prediction.median[data.prediction.median.length - 1] - data.currentPrice) / data.currentPrice) * 100,
      chartData: chartData
    });
    setLoading(false);
  } catch (err) {
    setError("Error en el motor de predicción.");
    setLoading(false);
  }
};
```

