```python
from flask import Flask, request, jsonify
from flask_cors import CORS
import numpy as np
import requests
from datetime import datetime, timedelta
from typing import Dict, List, Optional
import os
from dotenv import load_dotenv

load_dotenv()

app = Flask(__name__)
CORS(app)  # Habilitar CORS para React

# Modelo avanzado de predicción
class AdvancedFinancialPredictor:
    def __init__(self):
        self.cache = {}

    def fetch_real_price(self, symbol: str) -> Optional[float]:
        """Obtiene precio real desde APIs externas"""
        cache_key = f"price_{symbol}_{datetime.now().strftime('%Y%m%d%H')}"

        if cache_key in self.cache:
            return self.cache[cache_key]

        try:
            if symbol.endswith('USDT'):
                # Binance API
                response = requests.get(
                    f"https://api.binance.com/api/v3/ticker/price?symbol={symbol}",
                    timeout=5
                )
                if response.status_code == 200:
                    data = response.json()
                    price = float(data['price'])
                    self.cache[cache_key] = price
                    return price

            elif symbol.startswith('USD-'):
                # DolarAPI
                dolar_type = symbol.split('-')[1].lower()
                response = requests.get(
                    f"https://dolarapi.com/v1/dolares/{dolar_type}",
                    timeout=5
                )
                if response.status_code == 200:
                    data = response.json()
                    price = float(data['compra'])
                    self.cache[cache_key] = price
                    return price

        except Exception as e:
            print(f"Error fetching price for {symbol}: {e}")

        return None

    def nonlinear_prediction_model(self, 
                                  current_price: float,
                                  historical_data: List[float],
                                  time_steps: int,
                                  volatility_factor: float = 0.02) -> Dict:
        """
        Modelo de predicción no lineal basado en PDEs financieras

        ∂P/∂t = μP + σP∇²P + β|∇P|² + η(x,t)

        Donde:
        - P: Precio del activo
        - μ: Drift (tendencia)
        - σ: Volatilidad
        - β: Coeficiente no lineal (efectos de retroalimentación)
        - η: Ruido estocástico
        """

        # Análisis de datos históricos
        if len(historical_data) < 10:
            # Si no hay suficiente historial, generamos datos simulados
            historical_data = self._generate_synthetic_data(current_price, 50)

        # Calcular parámetros del modelo
        returns = np.diff(np.log(historical_data))

        if len(returns) == 0:
            mu = 0.0005  # Drift pequeño positivo por defecto
            sigma = volatility_factor
        else:
            mu = np.mean(returns)  # Drift promedio
            sigma = np.std(returns) * np.sqrt(252)  # Volatilidad anualizada

        # Coeficiente no lineal basado en autocorrelación
        if len(returns) > 5:
            autocorr = np.correlate(returns - returns.mean(), 
                                   returns - returns.mean(), mode='full')
            autocorr = autocorr[len(autocorr)//2:]
            beta = autocorr[1] / autocorr[0] if autocorr[0] != 0 else 0.1
            beta = np.clip(beta, 0.05, 0.3)
        else:
            beta = 0.15

        # Simulación Monte Carlo con PDE no lineal
        n_simulations = 500
        predictions = []

        for _ in range(n_simulations):
            price_trajectory = [current_price]
            price = current_price

            for step in range(time_steps):
                # Ecuación de evolución no lineal
                dt = 1.0 / 252  # Paso temporal diario

                # Término lineal (drift)
                linear_term = mu * price * dt

                # Término difusivo (volatilidad)
                diffusion = sigma * price * np.random.randn() * np.sqrt(dt)

                # Término no lineal (retroalimentación)
                if step > 0:
                    price_change = price_trajectory[-1] - price_trajectory[-2] if len(price_trajectory) > 1 else 0
                    nonlinear_term = beta * price_change**2 * dt
                else:
                    nonlinear_term = 0

                # Ruido estocástico adicional
                noise = 0.01 * price * np.random.randn() * np.sqrt(dt)

                # Actualización del precio
                price = price + linear_term + diffusion + nonlinear_term + noise
                price = max(price, current_price * 0.5)  # Límite inferior

                price_trajectory.append(price)

            predictions.append(price_trajectory[-1])

        # Análisis estadístico de las simulaciones
        predictions_array = np.array(predictions)

        return {
            'median': float(np.median(predictions_array)),
            'mean': float(np.mean(predictions_array)),
            'std': float(np.std(predictions_array)),
            'percentile_5': float(np.percentile(predictions_array, 5)),
            'percentile_25': float(np.percentile(predictions_array, 25)),
            'percentile_75': float(np.percentile(predictions_array, 75)),
            'percentile_95': float(np.percentile(predictions_array, 95)),
            'all_simulations': predictions_array.tolist()[:100],  # Limitar para respuesta
            'model_parameters': {
                'mu': float(mu),
                'sigma': float(sigma),
                'beta': float(beta),
                'n_simulations': n_simulations
            }
        }

    def _generate_synthetic_data(self, current_price: float, n_points: int) -> List[float]:
        """Genera datos históricos sintéticos basados en precio actual"""
        prices = [current_price]

        for i in range(1, n_points):
            # Random walk with drift
            drift = 0.0002 * i
            volatility = 0.015 * (1 + 0.5 * np.sin(i/10))  # Volatilidad variable
            noise = np.random.randn() * volatility

            new_price = prices[-1] * (1 + drift + noise)
            prices.append(new_price)

        return prices

    def calculate_risk_metrics(self, predictions: np.ndarray, current_price: float) -> Dict:
        """Calcula métricas de riesgo avanzadas"""
        returns_sim = (predictions - current_price) / current_price

        # Value at Risk (VaR) 95%
        var_95 = np.percentile(returns_sim, 5) * current_price

        # Expected Shortfall (CVaR)
        worst_5_percent = returns_sim[returns_sim <= np.percentile(returns_sim, 5)]
        expected_shortfall = np.mean(worst_5_percent) * current_price if len(worst_5_percent) > 0 else 0

        # Probabilidad de ganancia
        prob_profit = np.mean(returns_sim > 0) * 100

        # Ratio de Sharpe simulado
        excess_returns = returns_sim - 0.02/252  # Asumiendo tasa libre de riesgo 2% anual
        sharpe_ratio = np.mean(excess_returns) / np.std(excess_returns) * np.sqrt(252) if np.std(excess_returns) > 0 else 0

        return {
            'var_95': float(abs(var_95)),
            'expected_shortfall': float(abs(expected_shortfall)),
            'prob_profit': float(prob_profit),
            'sharpe_ratio': float(sharpe_ratio),
            'max_drawdown_sim': float(np.min(returns_sim) * current_price),
            'skewness': float(np.mean(((returns_sim - returns_sim.mean()) / returns_sim.std())**3)) if returns_sim.std() > 0 else 0
        }

