@app.route('/api/predict', methods=['POST'])
def predict():
    """Predicción avanzada con modelo no lineal"""
    try:
        data = request.json
        symbol = data.get('symbol', 'BTCUSDT')
        time_value = int(data.get('timeValue', 15))
        time_unit = data.get('timeUnit', 'minute')

        # Convertir a pasos temporales
        if time_unit == 'minute':
            time_steps = time_value
            time_label = 'minutos'
        elif time_unit == 'hour':
            time_steps = time_value * 60
            time_label = 'horas'
        elif time_unit == 'day':
            time_steps = time_value
            time_label = 'días'
        elif time_unit == 'month':
            time_steps = time_value * 21  ~Días hábiles
            time_label = 'meses'
        else:
            time_steps = time_value
            time_label = 'unidades'

        # Obtener precio actual
        current_price = predictor.fetch_real_price(symbol)

        if current_price is None:
            return jsonify({'error': 'No se pudo obtener el precio actual'}), 400

        # Obtener datos históricos (últimos 100 puntos)
        historical_data = []
        try:
            if symbol.endswith('USDT'):
                # Para Binance, obtener datos históricos (simulado por ahora)
                historical_data = predictor._generate_synthetic_data(current_price, 100)
            else:
                historical_data = [current_price] * 100
        except:
            historical_data = predictor._generate_synthetic_data(current_price, 100)

        # Ejecutar predicción con modelo no lineal
        prediction_result = predictor.nonlinear_prediction_model(
            current_price=current_price,
            historical_data=historical_data,
            time_steps=time_steps
        )

        # Calcular métricas de riesgo
        risk_metrics = predictor.calculate_risk_metrics(
            np.array(prediction_result['all_simulations']),
            current_price
        )

        # Generar datos para gráfico
        chart_data = []
        now = datetime.now()

        # Historial (simulado)
        for i in range(min(20, len(historical_data))):
            time_point = now - timedelta(minutes=(20-i)*5)
            chart_data.append({
                'time': time_point.strftime('%H:%M'),
                'price': historical_data[-(20-i)] if i < len(historical_data) else current_price,
                'type': 'history'
            })

        # Predicciones futuras
        future_times = []
        if time_unit == 'minute':
            for i in range(1, time_value + 1):
                future_times.append((now + timedelta(minutes=i)).strftime('%H:%M'))
        else:
            for i in range(1, 21):  # 20 puntos en el futuro
                if time_unit == 'hour':
                    future_times.append((now + timedelta(hours=i)).strftime('%H:%M'))
                else:
                    future_times.append((now + timedelta(days=i)).strftime('%m/%d'))

        # Media de simulaciones para gráfico
        if len(prediction_result['all_simulations']) >= 20:
            for i, price in enumerate(prediction_result['all_simulations'][:20]):
                if i < len(future_times):
                    chart_data.append({
                        'time': future_times[i],
                        'price': price,
                        'type': 'prediction'
                    })

        return jsonify({
            'success': True,
            'symbol': symbol,
            'currentPrice': current_price,
            'prediction': {
                'median': prediction_result['median'],
                'mean': prediction_result['mean'],
                'confidenceInterval': {
                    'lower': prediction_result['percentile_5'],
                    'upper': prediction_result['percentile_95']
                },
                'timeHorizon': f"{time_value} {time_label}"
            },
            'riskMetrics': risk_metrics,
            'chartData': chart_data,
            'modelInfo': {
                'type': 'Nonlinear PDE Model',
                'parameters': prediction_result['model_parameters'],
                'timestamp': datetime.now().isoformat()
            }
        })

    except Exception as e:
        return jsonify({'error': str(e)}), 500

