```javascript
// Configuración
const API_URL = 'https://tu-backend.herokuapp.com'; // Cambiar por la URL de tu backend

// Elementos del DOM
const assetSearch = document.getElementById('assetSearch');
const selectedAsset = document.getElementById('selectedAsset');
const predictBtn = document.getElementById('predictBtn');
const timeHorizon = document.getElementById('timeHorizon');
const timeValue = document.getElementById('timeValue');
const timeUnit = document.getElementById('timeUnit');
const resultsDiv = document.getElementById('results');
const priceChart = document.getElementById('priceChart');

let currentAsset = null;
let chartInstance = null;

// Event Listeners
assetSearch.addEventListener('input', debounce(searchAssets, 300));
timeHorizon.addEventListener('input', function() {
    timeValue.textContent = this.value;
});
predictBtn.addEventListener('click', generatePrediction);

// Funciones
async function searchAssets() {
    const query = assetSearch.value.trim();
    if (!query) return;

    try {
        const response = await fetch(`${API_URL}/api/assets`);
        const assets = await response.json();
        const filtered = assets.filter(a => 
            a.symbol.includes(query.toUpperCase()) || 
            a.name.toLowerCase().includes(query.toLowerCase())
        );

        // Mostrar resultados (simplificado)
        if (filtered.length > 0) {
            selectAsset(filtered[0]);
        }
    } catch (error) {
        console.error('Error buscando activos:', error);
    }
}

function selectAsset(asset) {
    currentAsset = asset;
    updateSelectedAssetUI();
    fetchCurrentPrice();
}

function updateSelectedAssetUI() {
    document.getElementById('assetSymbol').textContent = currentAsset.symbol;
    document.getElementById('assetName').textContent = currentAsset.name;
}

async function fetchCurrentPrice() {
    if (!currentAsset) return;

    try {
        const response = await fetch(`${API_URL}/api/price/${currentAsset.symbol}`);
        const data = await response.json();

        if (data.error) throw new Error(data.error);

        document.getElementById('currentPrice').textContent = `$${data.price.toFixed(2)}`;
        // Aquí podrías calcular el cambio porcentual si tienes datos históricos
    } catch (error) {
        console.error('Error obteniendo precio:', error);
    }
}

async function generatePrediction() {
    if (!currentAsset) {
        alert('Selecciona un activo primero');
        return;
    }

    const timeValue = timeHorizon.value;
    const timeUnit = 'day'; // Por simplificación, podrías tener un selector

    try {
        const response = await fetch(`${API_URL}/api/predict`, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({
                symbol: currentAsset.symbol,
                timeValue: timeValue,
                timeUnit: timeUnit
            })
        });

        const data = await response.json();

        if (data.error) throw new Error(data.error);

        displayResults(data);
        updateChart(data.chartData);
    } catch (error) {
        console.error('Error generando predicción:', error);
        resultsDiv.innerHTML = `<p class="text-red-500">Error: ${error.message}</p>`;
    }
}

function displayResults(data) {
    const prediction = data.prediction;
    const change = ((prediction.median - data.currentPrice) / data.currentPrice * 100).toFixed(2);
    const changeClass = change >= 0 ? 'text-green-500' : 'text-red-500';

    resultsDiv.innerHTML = `
        <div class="grid grid-cols-2 gap-4">
            <div class="bg-gray-700 p-4 rounded-lg">
                <p class="text-gray-400">Precio Actual</p>
                <p class="text-2xl font-bold">$${data.currentPrice.toFixed(2)}</p>
            </div>
            <div class="bg-gray-700 p-4 rounded-lg">
                <p class="text-gray-400">Precio Predicho</p>
                <p class="text-2xl font-bold">$${prediction.median.toFixed(2)}</p>
                <p class="${changeClass}">${change >= 0 ? '+' : ''}${change}%</p>
            </div>
        </div>
        <div class="mt-4">
            <p class="text-gray-400">Intervalo de confianza (95%)</p>
            <p>$${prediction.confidenceInterval.lower.toFixed(2)} - $${prediction.confidenceInterval.upper.toFixed(2)}</p>
        </div>
    `;
}

function updateChart(chartData) {
    const ctx = priceChart.getContext('2d');

    if (chartInstance) {
        chartInstance.destroy();
    }

    chartInstance = new Chart(ctx, {
        type: 'line',
        data: {
            labels: chartData.map(d => d.time),
            datasets: [{
                label: 'Precio',
                data: chartData.map(d => d.price),
                borderColor: 'rgb(59, 130, 246)',
                backgroundColor: 'rgba(59, 130, 246, 0.1)',
                fill: true,
                tension: 0.4
            }]
        },
        options: {
            responsive: true,
            plugins: {
                legend: {
                    display: false
                }
            },
            scales: {
                y: {
                    beginAtZero: false,
                    grid: {
                        color: 'rgba(255, 255, 255, 0.1)'
                    },
                    ticks: {
                        color: '#9CA3AF'
                    }
                },
                x: {
                    grid: {
                        color: 'rgba(255, 255, 255, 0.1)'
                    },
                    ticks: {
                        color: '#9CA3AF'
                    }
                }
            }
        }
    });
}

// Utilidades
function debounce(func, wait) {
    let timeout;
    return function executedFunction(...args) {
        const later = () => {
            clearTimeout(timeout);
            func(...args);
        };
        clearTimeout(timeout);
        timeout = setTimeout(later, wait);
    };
}

// Inicialización
document.addEventListener('DOMContentLoaded', function() {
    // Cargar activos por defecto
    fetch(`${API_URL}/api/assets`)
        .then(res => res.json())
        .then(assets => {
            if (assets.length > 0) {
                selectAsset(assets[0]);
            }
        });
});
