### **7.2: `frontend/app.js`**
```javascript
// Configuración
const API_URL = window.location.hostname === 'localhost' 
    ? 'http://localhost:5000' 
    : 'https://tu-backend.herokuapp.com'; // Cambiar por tu URL

// Variables globales
let currentAsset = null;
let priceChart = null;
let assetsList = [];

// Inicialización
document.addEventListener('DOMContentLoaded', async () => {
    await loadAssets();
    setupEventListeners();
    updateTimeDisplay();
});

// Cargar lista de activos
async function loadAssets() {
    try {
        const response = await fetch(`${API_URL}/api/assets`);
        assetsList = await response.json();

        if (assetsList.length > 0) {
            selectAsset(assetsList[0]);
        }
    } catch (error) {
        console.error('Error cargando activos:', error);
        // Datos de respaldo
        assetsList = [
            {"symbol": "BTCUSDT", "name": "Bitcoin"},
            {"symbol": "ETHUSDT", "name": "Ethereum"},
            {"symbol": "USD-BLUE", "name": "Dólar Blue"}
        ];
        selectAsset(assetsList[0]);
    }
}

// Configurar event listeners
function setupEventListeners() {
    const searchInput = document.getElementById('assetSearch');
    const timeSlider = document.getElementById('timeHorizon');

    searchInput.addEventListener('input', debounce(searchAssets, 300));
    timeSlider.addEventListener('input', function() {
        document.getElementById('timeValue').textContent = this.value;
    });
}

// Buscar activos
function searchAssets() {
    const query = document.getElementById('assetSearch').value.toLowerCase();

    if (!query) return;

    const filtered = assetsList.filter(asset => 
        asset.symbol.toLowerCase().includes(query) || 
        asset.name.toLowerCase().includes(query)
    );

    if (filtered.length > 0) {
        selectAsset(filtered[0]);
    }
}

// Seleccionar activo
async function selectAsset(asset) {
    currentAsset = asset;

    // Actualizar UI
    document.getElementById('assetSymbol').textContent = asset.symbol;
    document.getElementById('assetName').textContent = asset.name;
    document.getElementById('assetSearch').value = '';

    // Obtener precio actual
    await fetchCurrentPrice();
}

// Obtener precio actual
async function fetchCurrentPrice() {
    if (!currentAsset) return;

    try {
        const response = await fetch(`${API_URL}/api/price/${currentAsset.symbol}`);
        const data = await response.json();

        if (data.error) throw new Error(data.error);

        const price = data.price.toFixed(2);
        document.getElementById('currentPrice').textContent = `$${price}`;

    } catch (error) {
        console.error('Error obteniendo precio:', error);
        // Precio simulado
        const simulatedPrice = (43000 + Math.random() * 1000).toFixed(2);
        document.getElementById('currentPrice').textContent = `$${simulatedPrice}`;
    }
}

// Generar predicción
async function generatePrediction() {
    if (!currentAsset) {
        alert('Por favor, selecciona un activo primero');
        return;
    }

    const timeValue = document.getElementById('timeHorizon').value;

    try {
        const response = await fetch(`${API_URL}/api/predict`, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({
                symbol: currentAsset.symbol,
                timeValue: parseInt(timeValue),
                timeUnit: 'minute'
            })
        });

        const data = await response.json();

        if (data.error) throw new Error(data.error);

        displayResults(data);

    } catch (error) {
        console.error('Error en predicción:', error);
        // Datos simulados para demostración
        displayResults(generateDemoData());
    }
}

// Mostrar resultados
function displayResults(data) {
    const resultsDiv = document.getElementById('results');
    const prediction = data.prediction;
    const change = ((prediction.median - data.currentPrice) / data.currentPrice * 100).toFixed(2);
    const changeClass = change >= 0 ? 'text-green-500' : 'text-red-500';

    resultsDiv.innerHTML = `
        <h2 class="text-xl font-bold mb-6">
            <i class="fas fa-chart-line text-green-500 mr-2"></i>Resultados
        </h2>

        <div class="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
            <div class="bg-gray-800 p-4 rounded-xl">
                <p class="text-gray-400 text-sm">Precio Actual</p>
                <p class="text-2xl font-bold">$${data.currentPrice.toFixed(2)}</p>
            </div>

            <div class="bg-gray-800 p-4 rounded-xl">
                <p class="text-gray-400 text-sm">Precio Predicho</p>
                <p class="text-2xl font-bold">$${prediction.median.toFixed(2)}</p>
            </div>

            <div class="bg-gray-800 p-4 rounded-xl">
                <p class="text-gray-400 text-sm">Variación</p>
                <p class="text-2xl font-bold ${changeClass}">${change >= 0 ? '+' : ''}${change}%</p>
            </div>
        </div>

        <div class="mb-6">
            <p class="text-gray-400 text-sm mb-2">Intervalo de confianza (95%)</p>
            <p class="text-lg">$${prediction.percentile_5.toFixed(2)} - $${prediction.percentile_95.toFixed(2)}</p>
        </div>

        <canvas id="priceChart" height="300"></canvas>
    `;

    updateChart(data.chartData);
}

// Actualizar gráfico
function updateChart(chartData) {
    const ctx = document.getElementById('priceChart').getContext('2d');

    if (priceChart) {
        priceChart.destroy();
    }

    // Separar datos históricos y de predicción
    const historyData = chartData.filter(d => d.type === 'history');
    const predictionData = chartData.filter(d => d.type === 'prediction');

    priceChart = new Chart(ctx, {
        type: 'line',
        data: {
            labels: [...historyData.map(d => d.time), ...predictionData.map(d => d.time)],
            datasets: [
                {
                    label: 'Histórico',
                    data: [...historyData.map(d => d.price), ...Array(predictionData.length).fill(null)],
                    borderColor: '#3b82f6',
                    backgroundColor: 'rgba(59, 130, 246, 0.1)',
                    fill: true,
                    tension: 0.4
                },
                {
                    label: 'Predicción',
                    data: [...Array(historyData.length).fill(null), ...predictionData.map(d => d.price)],
                    borderColor: '#10b981',
                    borderDash: [5, 5],
                    tension: 0.4
                }
            ]
        },
        options: {
            responsive: true,
            plugins: {
                legend: {
                    labels: {
                        color: '#9ca3af'
                    }
                }
            },
            scales: {
                x: {
                    grid: {
                        color: 'rgba(255, 255, 255, 0.1)'
                    },
                    ticks: {
                        color: '#9ca3af'
                    }
                },
                y: {
                    grid: {
                        color: 'rgba(255, 255, 255, 0.1)'
                    },
                    ticks: {
                        color: '#9ca3af',
                        callback: function(value) {
                            return '$' + value.toFixed(0);
                        }
                    }
                }
            }
        }
    });
}

// Generar datos de demostración
function generateDemoData() {
    const currentPrice = 43250 + Math.random() * 1000;
    const predictedPrice = currentPrice * (1 + (Math.random() * 0.1 - 0.05));

    // Generar datos para gráfico
    const chartData = [];
    const now = new Date();

    // Historial
    for (let i = 20; i >= 0; i--) {
        const time = new Date(now);
        time.setMinutes(time.getMinutes() - i * 5);

        chartData.push({
            time: time.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
            price: currentPrice * (1 + (Math.random() - 0.5) * 0.02 * i/20),
            type: 'history'
        });
    }

    // Predicción
    for (let i = 1; i <= 20; i++) {
        const time = new Date(now);
        time.setMinutes(time.getMinutes() + i * 5);

        const t = i / 20;
        const price = currentPrice * (1 - t) + predictedPrice * t;

        chartData.push({
            time: time.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
            price: price + (Math.random() - 0.5) * 100,
            type: 'prediction'
        });
    }

    return {
        success: true,
        currentPrice: currentPrice,
        prediction: {
            median: predictedPrice,
            mean: predictedPrice * 1.01,
            percentile_5: predictedPrice * 0.97,
            percentile_95: predictedPrice * 1.03
        },
        chartData: chartData,
        riskMetrics: {
            prob_profit: 65 + Math.random() * 20,
            var_95: currentPrice * 0.02,
            sharpe_ratio: 1.2 + Math.random() * 0.5
        }
    };
}

// Utilidades
function debounce(func, wait) {
    let timeout;
    return function executedFunction(...args) {
        const later = () => {
            clearTimeout(timeout);
            func(...args);
        };
        clearTimeout(timeout);
        timeout = setTimeout(later, wait);
    };
}

function updateTimeDisplay() {
    const now = new Date();
    document.getElementById('timeValue').textContent = 
        document.getElementById('timeHorizon').value;
}
```

